        // Scenario 6: Reset inputs to c = 0 and d = 0
        c = 0; d = 0;
        #2; // Wait for 2 time units to stabilize
        $fdisplay(file, "scenario: 6, c = %d, d = %d, mux_in = %b", c, d, mux_in);

        // Close the file
        $fclose(file);

        // End simulation
        $finish;
    end
